package com.jarvis.assistant;
import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.net.Uri;
import android.speech.RecognizerIntent;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
public class MainActivity extends Activity {
 private TextView status,conversation,voiceStatus,versionStatus,deviceHistory;private EditText pairing,prompt;private final Handler h=new Handler(Looper.getMainLooper());private boolean visible=false,loading=false,manualInProgress=false,resumeAfterDictation=false;private final Runnable poller=new Runnable(){public void run(){if(!visible)return;refresh();voiceStatus.setText(VoiceService.status+(VoiceService.lastHeard.isEmpty()?"":"\nÚltimo pedido: "+VoiceService.lastHeard)+(VoiceService.lastError.isEmpty()?"":"\nDiagnóstico: "+VoiceService.lastError));h.postDelayed(this,1500);}};
 @Override public void onCreate(Bundle saved){super.onCreate(saved);if(saved!=null){manualInProgress=saved.getBoolean("manualInProgress",false);resumeAfterDictation=saved.getBoolean("resumeAfterDictation",false);}getWindow().setStatusBarColor(Color.rgb(6,17,24));getWindow().setNavigationBarColor(Color.rgb(6,17,24));ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(24,36,24,32);box.setBackgroundColor(Color.rgb(6,17,24));scroll.addView(box);setContentView(scroll);
  TextView title=text("JARVIS  /  ANDROID",25);title.setTextColor(Color.rgb(70,222,241));box.addView(title);box.addView(text("Tu asistente de PC, desde tu celular o tablet. Versión 1.2.1",14));
  voiceStatus=text(VoiceService.status,15);box.addView(voiceStatus);button(box,"Activar escucha en segundo plano",()->activate());button(box,"Pausar escucha",()->pauseListening());
  status=text("Vincula tu PC desde Ajustes > Android. Ambos deben estar en la misma red Wi-Fi o VPN privada.",15);box.addView(status);
  prompt=new EditText(this);prompt.setTextColor(Color.WHITE);prompt.setHintTextColor(Color.LTGRAY);prompt.setHint("Escribe tu petición…");prompt.setMinLines(2);box.addView(prompt);
  button(box,"Enviar pedido",()->send(prompt.getText().toString()));button(box,"Hablar y enviar",()->dictate());
  box.addView(text("Manos libres: activa la escucha y di Hola Jarvis seguido de tu pedido. Hablar y enviar manda el dictado al terminar.",14));
  pairing=new EditText(this);pairing.setTextColor(Color.WHITE);pairing.setHintTextColor(Color.LTGRAY);pairing.setHint("Pega el código JSON de vinculación de tu PC");pairing.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);pairing.setMinLines(2);box.addView(pairing);
  button(box,"Importar archivo de vinculación",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,20);});
  button(box,"Vincular PC",()->savePairing(pairing.getText().toString()));
  box.addView(text("Los pedidos de abrir apps se ejecutan en este Android. Añade «en mi PC» para controlar la computadora vinculada.",14));button(box,"Habilitar control del dispositivo",()->new AlertDialog.Builder(this).setTitle("Control opcional de Android").setMessage("Permite identificar la app en primer plano y ejecutar inicio, atrás, recientes y abrir aplicaciones por tus pedidos. No lee textos de otras pantallas ni toca botones dentro de otras apps. Debes habilitarlo tú en los ajustes de Accesibilidad y puedes desactivarlo allí.").setNegativeButton("Cancelar",null).setPositiveButton("Abrir ajustes",(dialog,which)->{try{Intent access=new Intent("android.settings.ACCESSIBILITY_DETAILS_SETTINGS").putExtra(Intent.EXTRA_COMPONENT_NAME,new ComponentName(this,DeviceAccessService.class));startActivity(access);}catch(Exception e){startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS));}}).show());deviceHistory=text("Control local listo. Ejemplos: abre Chrome, vuelve al inicio, aplicaciones recientes.",15);deviceHistory.setTextIsSelectable(true);box.addView(deviceHistory);
  box.addView(text("Di Hola Jarvis y tu pedido, o di Hola Jarvis, espera Te escucho y habla. Al terminar se envía automáticamente. La escucha se recupera tras pausas y fallos temporales del micrófono; Android puede suspenderla. Mantener el micrófono y el procesador activos consume batería: usa Pausar escucha cuando no lo necesites.",13));CheckBox systemSpeech=new CheckBox(this);systemSpeech.setText("Permitir reconocimiento del sistema si falta el local (puede enviar audio a su proveedor y usar Internet)");systemSpeech.setTextColor(Color.LTGRAY);systemSpeech.setChecked(getSharedPreferences("jarvis",0).getBoolean("allowSystemRecognition",false));systemSpeech.setOnCheckedChangeListener((button,checked)->{getSharedPreferences("jarvis",0).edit().putBoolean("allowSystemRecognition",checked).apply();status.setText("Opción guardada. Pulsa Activar escucha para volver a intentarlo.");});box.addView(systemSpeech);box.addView(text("Esta opción es voluntaria. Durante la escucha, el proveedor del sistema podría procesar audio incluso antes de decir Hola Jarvis. Desactivada: solo se intenta reconocimiento local.",12));
  box.addView(text("Hablar y enviar manda la petición al terminar el dictado, sin pulsar Enviar. Para manos libres activa la escucha y di Hola Jarvis. El micrófono del teclado es independiente.",13));
  button(box,"Detener tarea de PC",()->new Thread(()->{try{Api.request(this,"/api/stop",new JSONObject());runOnUiThread(()->status.setText("Se solicitó detener la tarea."));}catch(Exception e){showError(e);}}).start());
  versionStatus=text(AppUpdates.message,13);box.addView(versionStatus);button(box,"Buscar actualizaciones",()->AppUpdates.check(this,true,()->versionStatus.setText(AppUpdates.message)));button(box,"Ver versiones en GitHub",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/floresroldanluis/Jarvis/releases"))));
  conversation=text("Aquí aparecerán tus pedidos y respuestas.",16);conversation.setTextIsSelectable(true);box.addView(conversation);
 }
 private TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextColor(Color.rgb(219,231,235));v.setTextSize(size);v.setPadding(0,10,0,10);return v;}
 private void button(LinearLayout parent,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setOnClickListener(v->action.run());parent.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 private void showError(Exception e){runOnUiThread(()->status.setText(e.getMessage()==null?"No se pudo conectar con tu PC.":e.getMessage()));}
 private void savePairing(String value){try{JSONObject p=new JSONObject(value);if(!p.getString("fingerprint").replace(":","").matches("[a-fA-F0-9]{64}")||!p.getString("token").matches("[a-f0-9]{64}"))throw new Exception("Código de vinculación inválido.");PairingStore.save(this,p.toString());pairing.setText("");status.setText("PC guardada. Probando conexión…");refresh();}catch(Exception e){showError(e);}}
 private void activate(){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},10);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},11);return;}getSharedPreferences("jarvis",0).edit().putBoolean("alwaysListen",true).apply();try{startForegroundService(new Intent(this,VoiceService.class));h.postDelayed(()->voiceStatus.setText(VoiceService.status),1000);}catch(Exception e){showError(e);}}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grant){super.onRequestPermissionsResult(code,permissions,grant);if(grant.length>0&&grant[0]==PackageManager.PERMISSION_GRANTED)activate();else status.setText("Sin este permiso puedes seguir escribiendo. Activa micrófono y notificaciones para la escucha.");}
 private void send(String text){if(text.trim().isEmpty())return;DeviceCommand local=DeviceCommand.parse(text);if(local!=null){String answer=DeviceControl.execute(this,local);deviceHistory.append("\n\nTÚ: "+text+"\nJARVIS (este Android): "+answer);prompt.setText("");status.setText(answer);return;}status.setText("Enviando…");new Thread(()->{try{Api.request(this,"/api/chat",new JSONObject().put("text",text.trim()).put("mode","auto"));runOnUiThread(()->{prompt.setText("");status.setText("Pedido enviado a tu PC.");refresh();});}catch(Exception e){showError(e);}},"jarvis-send").start();}
 private void refresh(){if(loading)return;try{PairingStore.read(this);}catch(Exception e){status.setText("Control local disponible. Vincula una PC para documentos, correos y consultas a Codex.");return;}loading=true;new Thread(()->{try{JSONObject s=Api.request(this,"/api/state",null);JSONArray messages=s.optJSONArray("messages");StringBuilder out=new StringBuilder();if(messages!=null)for(int i=0;i<messages.length();i++){JSONObject m=messages.getJSONObject(i);out.append("user".equals(m.optString("role"))?"TÚ\n":"JARVIS\n").append(m.optString("text")).append("\n\n");}runOnUiThread(()->{conversation.setText(out.toString());status.setText(s.optBoolean("busy")?"JARVIS está trabajando en tu PC…":"Conectado a tu PC.");});}catch(Exception e){showError(e);}finally{loading=false;}},"jarvis-refresh").start();}
 @Override protected void onResume(){super.onResume();visible=true;h.post(poller);if(!manualInProgress&&VoiceService.enabled(this)&&VoiceService.running)startService(new Intent(this,VoiceService.class).setAction(VoiceService.RESUME));if(!manualInProgress&&VoiceService.enabled(this)&&!VoiceService.running&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED&&(Build.VERSION.SDK_INT<33||checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED))activate();AppUpdates.check(this,false,()->versionStatus.setText(AppUpdates.message));}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putBoolean("manualInProgress",manualInProgress);out.putBoolean("resumeAfterDictation",resumeAfterDictation);}
 @Override protected void onPause(){visible=false;h.removeCallbacks(poller);super.onPause();}
 private void pauseListening(){getSharedPreferences("jarvis",0).edit().putBoolean("alwaysListen",false).apply();if(VoiceService.running)startService(new Intent(this,VoiceService.class).setAction(VoiceService.STOP));else stopService(new Intent(this,VoiceService.class));VoiceService.status="Escucha pausada por ti";voiceStatus.setText(VoiceService.status);}
 private void dictate(){if(manualInProgress)return;manualInProgress=true;resumeAfterDictation=VoiceService.running;if(resumeAfterDictation)startService(new Intent(this,VoiceService.class).setAction(VoiceService.SUSPEND));h.postDelayed(()->{try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"es-ES").putExtra(RecognizerIntent.EXTRA_PROMPT,"Habla: se enviará al terminar");startActivityForResult(i,21);}catch(Exception e){status.setText("No hay servicio de dictado. Puedes escribir.");finishDictation();}},400);}
 private void finishDictation(){manualInProgress=false;if(resumeAfterDictation&&VoiceService.enabled(this)){if(VoiceService.running)startService(new Intent(this,VoiceService.class).setAction(VoiceService.RESUME));else activate();}resumeAfterDictation=false;}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);
  if(request==21){try{if(result==RESULT_OK&&data!=null){java.util.ArrayList<String> values=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(values!=null&&!values.isEmpty()){String instruction=VoiceTrigger.manual(values.get(0));prompt.setText(instruction);if(instruction.isEmpty()){status.setText("Te escuché saludar. Di Hola Jarvis seguido de tu pedido en la escucha de fondo.");}else send(instruction);}}else status.setText("Dictado cancelado. No envié ningún pedido.");}finally{finishDictation();}return;}
  if(result!=RESULT_OK||data==null)return;
  if(request==20){try(InputStream in=getContentResolver().openInputStream(data.getData())){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1){if(out.size()+n>8192)throw new IOException("Archivo demasiado grande.");out.write(b,0,n);}savePairing(out.toString("UTF-8"));}catch(Exception e){showError(e);}}
 }
}